11	// V2: Applies account-type defaults (influencer, professional, brand, affiliate) to new professionals and their sites. Handles config inheritance and affiliate-specific overlays.
12	class AccountTypeDefaultsService
13	{
14	    public function __construct(
15	        private readonly SectionVisibilityService $visibilityService,
16	    ) {}
17	
18	    /**
19	     * Resolve the effective config for a professional type, handling inheritance.
20	     */
21	    public function resolveDefaults(string $professionalType): array
22	    {
23	        $all = config('partna.account_type_defaults', []);
24	        $typeConfig = $all[$professionalType] ?? $all['influencer'] ?? [];
25	
26	        if (isset($typeConfig['inherits'])) {
27	            $parent = $all[$typeConfig['inherits']] ?? [];
28	            $typeConfig = array_replace_recursive($parent, $typeConfig);
29	            unset($typeConfig['inherits']);
30	        }
31	
32	        return $typeConfig;
33	    }
34	
35	    /**
36	     * Apply defaults to a newly created professional's site and blocks.
37	     */
38	    public function applyDefaults(Professional $professional, Site $site): void
39	    {
40	        $defaults = $this->resolveDefaults($professional->professional_type);
41	
42	        // 1. Set is_published
43	        if (isset($defaults['is_published'])) {
44	            $site->is_published = (bool) $defaults['is_published'];
45	        }
46	
47	        // 2. Apply default site settings (e.g. brand system colours/font)
48	        if (isset($defaults['default_site_settings'])) {
49	            $existing = is_array($site->settings) ? $site->settings : [];
50	            $site->settings = array_replace_recursive($existing, $defaults['default_site_settings']);
51	        }
52	
53	        $site->save();
54	
55	        // 3. Create section blocks for allowed account-type sections.
56	        // For professional/influencer accounts we keep these enabled + draft by default.
57	        $allowedSections = $defaults['allowed_sections'] ?? [];
58	        $defaultSections = $defaults['default_sections'] ?? [];
59	        $sectionsToCreate = $professional->isBrand() ? $defaultSections : $allowedSections;
60	        foreach (array_values($sectionsToCreate) as $sortOrder => $blockType) {
61	            [$isEnabled] = $this->visibilityService->checkVisibilityRequirements(
62	                (string) $professional->id,
63	                (string) $site->id,
64	                $blockType
65	            );
66	            Block::query()->firstOrCreate(
67	                [
68	                    'professional_id' => $professional->id,
69	                    'site_id' => $site->id,
70	                    'block_group' => 'sections',
71	                    'block_type' => $blockType,
72	                ],
73	                [
74	                    'sort_order' => $sortOrder,
75	                    'is_enabled' => $isEnabled,
76	                    'is_active' => false,
77	                    'settings' => [],
78	                ]
79	            );
80	        }
81	
82	        // 4. Create default contact (for non-brand types)
83	        if (isset($defaults['default_contact'])) {
84	            $this->createDefaultContact($professional, $defaults['default_contact']);
85	        }
86	    }
87	
88	    /**
89	     * Apply affiliate-specific overlay when connecting to a brand.
90	     */
91	    public function applyAffiliateDefaults(
92	        Professional $professional,
93	        Site $site,
94	        string $brandProfessionalId
95	    ): void {
96	        $config = config('partna.account_type_defaults.affiliate', []);
97	
98	        // 1. Auto-enable shop section
99	        $autoSections = $config['auto_enable_sections'] ?? [];
100	        foreach ($autoSections as $blockType) {
101	            $block = Block::query()->firstOrNew([
102	                'professional_id' => $professional->id,
103	                'site_id' => $site->id,
104	                'block_group' => 'sections',
105	                'block_type' => $blockType,
106	            ]);
107	
108	            // is_enabled (data-requirements gate) is computed honestly so this
109	            // path stays consistent if auto_enable_sections grows beyond 'shop'
110	            // (which has no requirements). Today shop always evaluates to true,
111	            // so behaviour is unchanged for the current config.
112	            [$canBeEnabled] = $this->visibilityService->checkVisibilityRequirements(
113	                (string) $professional->id,
114	                (string) $site->id,
115	                $blockType,
116	            );
117	            $block->is_enabled = $canBeEnabled;
118	            $block->is_active = true;
119	
120	            if (! $block->exists) {
121	                $maxSort = Block::query()
122	                    ->where('site_id', $site->id)
123	                    ->where('block_group', 'sections')
124	                    ->max('sort_order');
125	
126	                $block->sort_order = is_null($maxSort) ? 0 : ((int) $maxSort + 1);
127	                $block->settings = [];
128	            }
129	
130	            $block->save();
131	        }
132	
133	    }
134	
135	    private function createDefaultContact(Professional $professional, array $contactData): void
136	    {
137	        $email = $contactData['email'] ?? null;
138	        if (! $email) {
139	            return;
140	        }
141	
142	        $exists = Customer::query()
143	            ->where('professional_id', $professional->id)
144	            ->where('email', $email)
145	            ->exists();
146	
147	        if (! $exists) {
148	            $customer = new Customer([
149	                'full_name' => $contactData['full_name'] ?? null,
150	                'email' => $email,
151	                'phone' => $contactData['phone'] ?? null,
152	                'source' => $contactData['source'] ?? 'system_default',
153	            ]);
154	            $customer->professional_id = $professional->id;
155	            $customer->save();
156	        }
157	
158	        // Create marketing subscription if configured
159	        if ($contactData['subscribed'] ?? false) {
160	            $sub = EmailSubscription::query()->firstOrNew([
161	                'professional_id' => $professional->id,
162	                'list_key' => 'marketing',
163	                'email_lc' => strtolower($email),
164	            ]);
165	
166	            if (! $sub->exists) {
167	                $sub->email = $email;
168	                $sub->full_name = $contactData['full_name'] ?? null;
169	                $sub->unsubscribe_token = EmailSubscription::newUnsubscribeToken();
170	                $sub->markSubscribed(['source' => 'account_default']);
171	                $sub->save();
172	            }
173	        }
174	    }
175	}
